// Webhook çıktısı: { headers, params, query, body }. Bize lazım olan body.
// Sonraki node'lar bu bilgilere $('İş bilgisi').first().json.xxx ile ulasir.
const body = $input.first().json.body || {};
if (!body.jobId || !body.statusUrl || !body.payloadUrl || !body.eventsUrl) {
  throw new Error('Geçersiz mesaj: jobId / statusUrl / payloadUrl / eventsUrl eksik.');
}
return [{ json: body }];

// Veri paketinden gunluge yazilacak kisa bir ozet cikarir.
// Tam paketi browser-worker backend'den kendisi çeker; burada sadece günlük için özet çıkarılır.
const p = $input.first().json;

const policy = { auto: [], askFirst: [], never: [] };
for (const [key, field] of Object.entries(p.policyFields || {})) {
  const value = String(field?.policy ?? 'Auto');
  if (value === 'Never') policy.never.push(key);
  else if (value === 'AskFirst') policy.askFirst.push(key);
  else policy.auto.push(key);
}

const counts = {
  workExperiences: (p.workExperiences || []).length,
  educations: (p.educations || []).length,
  languages: (p.languages || []).length,
  certificates: (p.certificates || []).length,
  screeningAnswers: (p.screeningAnswers || []).length,
  customFields: (p.customFields || []).length,
};
const warnings = p.warnings || [];

let message = `Veri paketi alındı: ${counts.workExperiences} deneyim, ${counts.educations} eğitim, ` +
  `${counts.screeningAnswers} hazır cevap. Önce sorulacak alan: ${policy.askFirst.length}, ` +
  `asla doldurulmayacak: ${policy.never.length}.`;
if (warnings.length) message += ` Uyarı: ${warnings.join(' | ')}`;

return [{
  json: {
    level: warnings.length ? 'Warning' : 'Info',
    message,
    counts,
    policy,
    warnings,
    hasCv: !!p.cv,
    cvUrl: p.cv?.downloadUrl ?? null,
    cvName: p.cv?.name ?? null,
  },
}];

// "Try/catch" dali: Hata cikisi (kirmizi) olan her node buraya baglidir.
// Hangi adimda ne oldugunu toplayip isi Failed yapacak mesaji hazirlar.
const err = $input.first().json.error;
let detail = 'Bilinmeyen hata';
if (typeof err === 'string') detail = err;
else if (err) detail = err.message || err.description || JSON.stringify(err);

const step = $prevNode.name;
return [{ json: { step, errorMessage: `${step} adımında hata: ${detail}`.slice(0, 1500) } }];

