// browser-worker'ın sonucunu (outcome) işin son durumuna çevirir.
//   Submitted        → Completed
//   ReadyForApproval → AwaitingApproval (form dolu, Gönder'e basılmadı)
//   NeedsInput       → AwaitingApproval (zorunlu alan eksik / önce sorulmalı)
//   Closed / Failed  → Failed
//   Cancelled        → hiçbir şey yapma (kullanıcı iptal etti, iş zaten bitti)
const r = $input.first().json;
let statusBody;
switch (r.outcome) {
  case 'Submitted':
    statusBody = { status: 'Completed', resultSummary: r.message, message: `Tarayıcı: ${r.filled.length} alan dolduruldu ve gönderildi.` };
    break;
  case 'ReadyForApproval':
    statusBody = { status: 'AwaitingApproval', message: r.message };
    break;
  case 'NeedsInput':
    statusBody = { status: 'AwaitingApproval', message: `Eksik bilgi: ${r.message}`.slice(0, 1900) };
    break;
  case 'Closed':
  case 'Failed':
    statusBody = { status: 'Failed', errorMessage: String(r.message).slice(0, 1900) };
    break;
  case 'Cancelled':
    return []; // boş çıktı = akış burada biter
  default:
    throw new Error('browser-worker bilinmeyen sonuç döndürdü: ' + r.outcome);
}
return [{ json: { statusBody, outcome: r.outcome } }];

// Sonucu yorumla ciktisindan WhatsApp bildirim metni olusturur.
const r = $input.first().json;
const jobId = $('İş bilgisi').first().json.jobId;
const sb = r.statusBody;
let text;
switch (sb.status) {
  case 'Completed':
    text = `✅ Başvuru gönderildi (iş #${jobId}). ${sb.message || ''}`;
    break;
  case 'AwaitingApproval':
    text = `⏳ Onay bekliyor (iş #${jobId}): ${sb.message || ''}`;
    break;
  case 'Failed':
    text = `❌ Başvuru başarısız (iş #${jobId}): ${sb.errorMessage || ''}`;
    break;
  default:
    text = `İş #${jobId} durumu: ${sb.status}`;
}
return [{ json: { text: text.slice(0, 1000) } }];

// Hata dalindan WhatsApp bildirim metni olusturur.
const jobId = $('İş bilgisi').first().json.jobId;
const errorMessage = $json.errorMessage;
return [{ json: { text: `❌ Başvuru başarısız (iş #${jobId}): ${errorMessage}`.slice(0, 1000) } }];
